const input = JSON.parse($input.item.json.input || '{}');
const { notification_type, user_name, context } = input;

const templates = {
  application_update: {
    title: `Application Status Update`,
    message: `Hi ${user_name}, your ${context.application_type || 'license'} application (ID: ${context.application_id || 'N/A'}) has been updated to: ${context.new_status || 'updated'}. ${context.notes || 'Please check your portal for details.'}`
  },
  document_request: {
    title: `Document Required`,
    message: `Hi ${user_name}, we need additional documentation for your application (ID: ${context.application_id || 'N/A'}). Required: ${context.document_type || 'additional documents'}. Please upload via the portal.`
  },
  appointment_reminder: {
    title: `Appointment Reminder`,
    message: `Hi ${user_name}, you have an upcoming ${context.appointment_type || 'appointment'} scheduled for ${context.date || 'soon'} at ${context.location || 'the testing center'}. Please arrive 15 minutes early.`
  },
  test_result: {
    title: `Test Results Available`,
    message: `Hi ${user_name}, your ${context.test_type || 'test'} results are available. Score: ${context.score || 'N/A'}. Status: ${context.passed ? 'PASSED' : 'NOT PASSED'}. Check the portal for full details.`
  },
  license_expiry: {
    title: `License Expiry Notice`,
    message: `Hi ${user_name}, your driver's license will expire on ${context.expiry_date || 'soon'}. Please start the renewal process to avoid any interruption.`
  },
  general: {
    title: context.title || `BLA Portal Update`,
    message: `Hi ${user_name}, ${context.message || 'You have a new update on the BLA Portal. Please log in to check.'}`
  }
};

const template = templates[notification_type] || templates.general;
return { title: template.title, message: template.message, type: notification_type };

